Lemma rw_junk_image : forall (m : word -> option byte) A bs,
  rw_bytes_b bsegs A bs = true -> (0 <= A)%Z -> (A + Z.of_nat (length bs) <= 2^64)%Z ->
  exists bs', rw_cells bsegs m A [CB (length bs) bs'].
